<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
type State = 0 | 1 | 2 | -1
type MainMode = 'add' | 'edit' | 'copy' | null
type SubMode = 'add' | 'edit' | 'copy' | null
interface Accessory { accessoryType:string; description:string|null; issueState:State; accessoryCategory:string; dataStamp:number; creator:string|null; createDate:string|null; reviser:string|null; reviseDate:string|null }
interface Category { accessoryCategory:string; description:string|null; issueState:State }
interface Property { accessory:string; accessoryVersion:string; propertyNo:string; defaultValue:string|null; propertySequence:number|null; description:string|null; issueState:State; dataStamp:number; creator:string|null; createDate:string|null; reviser:string|null; reviseDate:string|null }
interface Life { accessory:string; lifeManage:0|1; lifeScript:string|null; repairable:0|1|null; repairCycle:number|null; scrapType:0|1|null; scrapLife:number|null; lifeTolerance:0|1|null; timeCycle:number|null; alertTime:number|null; alertCount:number|null; dataStamp:number; creator:string|null; createDate:string|null; reviser:string|null; reviseDate:string|null }
interface ImportRow { accessoryType:string; accessoryCategory:string; description:string; result:string; message:string }
const props=defineProps<{apiBaseUrl:string;currentUserNo?:string;developmentPreview?:boolean}>()
const base=import.meta.env.BASE_URL.replace(/\/+$/,'')
const mock = computed(() => import.meta.env.DEV && props.developmentPreview === true)
const keys={main:'ymes-dev-mock:accessory-types:v1',category:'ymes-dev-mock:accessory-categories:v1',property:'ymes-dev-mock:accessory-properties:v1',life:'ymes-dev-mock:accessory-life:v1'}
const seedMain:Accessory[]=[
 {accessoryType:'DEV-ACC-01',description:'開發假資料：一般治具配件',issueState:0,accessoryCategory:'治具',dataStamp:0,creator:'DEV001',createDate:'2026-11-01T08:00:00+08:00',reviser:null,reviseDate:null},
 {accessoryType:'DEV-ACC-02',description:'開發假資料：已核准範例',issueState:2,accessoryCategory:'耗材',dataStamp:2,creator:'DEV001',createDate:'2026-11-02T08:00:00+08:00',reviser:'DEV002',reviseDate:'2026-11-04T09:10:00+08:00'},
 {accessoryType:'DEV-ACC-03',description:'開發假資料：簽核中不可刪除',issueState:1,accessoryCategory:'治具',dataStamp:1,creator:'DEV001',createDate:'2026-11-03T08:00:00+08:00',reviser:null,reviseDate:null},
 {accessoryType:'DEV-ACC-04',description:'開發假資料：不使用範例',issueState:-1,accessoryCategory:'量具',dataStamp:1,creator:'DEV001',createDate:'2026-11-04T08:00:00+08:00',reviser:'DEV002',reviseDate:'2026-11-05T10:00:00+08:00'}]
const seedCategories:Category[]=[{accessoryCategory:'治具',description:'治具類配件',issueState:2},{accessoryCategory:'耗材',description:'耗用型配件',issueState:2},{accessoryCategory:'量具',description:'量測工具',issueState:2}]
const seedProperties:Property[]=[
 {accessory:'DEV-ACC-01',accessoryVersion:'-1',propertyNo:'SIZE',defaultValue:'10',propertySequence:1,description:'開發用尺寸屬性',issueState:0,dataStamp:0,creator:'DEV001',createDate:'2026-11-01T08:00:00+08:00',reviser:null,reviseDate:null},
 {accessory:'DEV-ACC-01',accessoryVersion:'-1',propertyNo:'MATERIAL',defaultValue:'SUS304',propertySequence:2,description:'材質',issueState:2,dataStamp:1,creator:'DEV001',createDate:'2026-11-01T08:00:00+08:00',reviser:'DEV002',reviseDate:'2026-11-02T08:00:00+08:00'}]
const seedLife:Life[]=[{accessory:'DEV-ACC-01',lifeManage:1,lifeScript:'USE_COUNT <= 10000',repairable:1,repairCycle:10000,scrapType:0,scrapLife:3,lifeTolerance:0,timeCycle:null,alertTime:null,alertCount:500,dataStamp:1,creator:'DEV001',createDate:'2026-11-01T08:00:00+08:00',reviser:'DEV002',reviseDate:'2026-11-02T08:00:00+08:00'}]
const rows=ref<Accessory[]>([]), categories=ref<Category[]>([])
const status=ref<State>(0), keyword=ref(''), active=ref(''), selected=ref<string[]>([])
const loading=ref(false), busy=ref(false), error=ref(''), notice=ref('')
const mode=ref<MainMode>(null), form=ref({accessoryType:'',accessoryCategory:'',description:''})
const picker=ref(false), audit=ref({creator:'',createDate:'',reviser:'',reviseDate:''})
const propertyOpen=ref(false), properties=ref<Property[]>([]), propertyNo=ref(''), propertyMode=ref<SubMode>(null), propertyForm=ref({propertyNo:'',defaultValue:'',propertySequence:'1',description:''}), propertyError=ref(''), propertyNotice=ref('')
const lifeOpen=ref(false), life=ref<Life>(newLife('')), lifeError=ref(''), lifeNotice=ref('')
const importOpen=ref(false), importFile=ref(''), importRows=ref<ImportRow[]>([]), importError=ref('')
const visible=computed(()=>rows.value.filter(x=>x.issueState===status.value&&x.accessoryType.toLowerCase().includes(keyword.value.trim().toLowerCase())).sort((a,b)=>a.accessoryCategory.localeCompare(b.accessoryCategory)||a.accessoryType.localeCompare(b.accessoryType)))
const current=computed(()=>rows.value.find(x=>x.accessoryType===active.value)||null)
const targets=computed(()=>{const list=rows.value.filter(x=>selected.value.includes(x.accessoryType));return list.length?list:(current.value?[current.value]:[])})
const one=computed(()=>targets.value.length===1?targets.value[0]:null)
const editAllowed=computed(()=>one.value?.issueState===0)
const approveAllowed=computed(()=>targets.value.length>0&&targets.value.every(x=>x.issueState===0))
const deleteAllowed=computed(()=>targets.value.length>0&&targets.value.every(x=>[0,2,-1].includes(x.issueState)))
function newLife(id:string):Life{return{accessory:id,lifeManage:0,lifeScript:'',repairable:null,repairCycle:null,scrapType:null,scrapLife:null,lifeTolerance:null,timeCycle:null,alertTime:null,alertCount:null,dataStamp:0,creator:props.currentUserNo||'DEV001',createDate:new Date().toISOString(),reviser:null,reviseDate:null}}
function read<T>(key:string,seed:T[]):T[]{try{const s=localStorage.getItem(key);return s?JSON.parse(s) as T[]:structuredClone(seed)}catch{return structuredClone(seed)}}
function write<T>(key:string,value:T[]):void{localStorage.setItem(key,JSON.stringify(value))}
function dateText(value:string|null):string{if(!value)return'';const d=new Date(value);return Number.isNaN(+d)?value:d.toLocaleString('zh-TW',{hour12:false})}
function stateText(v:number):string{return({0:'未簽核',1:'簽核中',2:'已簽核','-1':'不使用'} as Record<string,string>)[String(v)]||'未知'}
function apiPath(path:string):string{if(!props.apiBaseUrl.trim())throw Error('目前環境尚未設定 API 位址。');return new URL(path.replace(/^\/+/,''),new URL(props.apiBaseUrl.replace(/\/+$/,'')+'/',location.origin)).toString()}

async function api<T>(path:string,init:RequestInit={}):Promise<T>{const r=await fetch(apiPath(path),{credentials:'include',...init});if(r.status===401){location.assign(base+'/');throw Error('登入狀態已逾期，請重新登入。')}if(!r.ok){const body=await r.json().catch(()=>null) as {title?:string;detail?:string;message?:string}|null;if(r.status===404)throw Error('配件類別 API 尚未建立，請依 todolist_homepc.md 完成資料表與 API。');throw Error(body?.detail||body?.message||body?.title||'API 回應錯誤 ('+r.status+')。')}return r.status===204?undefined as T:await r.json() as T}
function query():void{selected.value=selected.value.filter(id=>visible.value.some(x=>x.accessoryType===id));if(!visible.value.some(x=>x.accessoryType===active.value))active.value=visible.value[0]?.accessoryType||'';error.value='';notice.value=''}
async function load():Promise<void>{loading.value=true;error.value='';try{if(mock.value){rows.value=read(keys.main,seedMain);categories.value=read(keys.category,seedCategories)}else{rows.value=await api<Accessory[]>('api/equipment/accessory-types');categories.value=await api<Category[]>('api/equipment/accessory-categories')}query()}catch(e){rows.value=[];categories.value=[];error.value=e instanceof Error?e.message:'配件類別載入失敗。'}finally{loading.value=false}}
function selectRow(row:Accessory):void{active.value=row.accessoryType;error.value=''}
function toggle(id:string):void{selected.value=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id];active.value=id}
function openForm(next:Exclude<MainMode,null>):void{const row=one.value;if(next!=='add'&&!row){error.value='請先選取一筆配件類別。';return}if(next==='edit'&&row?.issueState!==0){error.value='只有未簽核資料可以修改。';return}mode.value=next;form.value=next==='edit'&&row?{accessoryType:row.accessoryType,accessoryCategory:row.accessoryCategory,description:row.description||''}:{accessoryType:'',accessoryCategory:next==='copy'&&row?row.accessoryCategory:'',description:next==='copy'&&row?row.description||'':''};audit.value=next==='edit'&&row?{creator:row.creator||'',createDate:dateText(row.createDate),reviser:props.currentUserNo||'',reviseDate:new Date().toLocaleString('zh-TW')}:{creator:props.currentUserNo||'DEV001',createDate:new Date().toLocaleString('zh-TW'),reviser:'',reviseDate:''};error.value=''}
function mainValidation():string{const id=form.value.accessoryType.trim();if(!id)return'配件類別為必填。';if(id.length>50)return'配件類別不可超過 50 個字元。';if(!form.value.accessoryCategory)return'配件分類為必填。';if(form.value.description.length>255)return'說明不可超過 255 個字元。';if(mode.value!=='edit'&&rows.value.some(x=>x.accessoryType.toUpperCase()===id.toUpperCase()))return'配件類別已存在。';return''}
async function saveMain(keep:boolean):Promise<void>{if(!mode.value)return;const problem=mainValidation();if(problem){error.value=problem;return}busy.value=true;error.value='';const old=current.value?.accessoryType||'',kind=mode.value,id=form.value.accessoryType.trim().toUpperCase();try{if(mock.value){const all=read(keys.main,seedMain),now=new Date().toISOString();if(kind==='edit'){const i=all.findIndex(x=>x.accessoryType===old);if(i<0)throw Error('找不到要修改的資料。');all[i]={...all[i],accessoryCategory:form.value.accessoryCategory,description:form.value.description.trim()||null,dataStamp:all[i].dataStamp+1,reviser:props.currentUserNo||'DEV001',reviseDate:now}}else{all.push({accessoryType:id,accessoryCategory:form.value.accessoryCategory,description:form.value.description.trim()||null,issueState:0,dataStamp:0,creator:props.currentUserNo||'DEV001',createDate:now,reviser:null,reviseDate:null});if(kind==='copy'){const source=read(keys.life,seedLife).find(x=>x.accessory===old);if(source){const lives=read(keys.life,seedLife).filter(x=>x.accessory!==id);lives.push({...source,accessory:id,dataStamp:0,creator:props.currentUserNo||'DEV001',createDate:now,reviser:null,reviseDate:null});write(keys.life,lives)}}}write(keys.main,all);rows.value=all}else{const body={accessoryType:id,accessoryCategory:form.value.accessoryCategory,description:form.value.description.trim()||null};if(kind==='edit')await api<void>('api/equipment/accessory-types/'+encodeURIComponent(old),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});else if(kind==='copy')await api<void>('api/equipment/accessory-types/'+encodeURIComponent(old)+'/copy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});else await api<void>('api/equipment/accessory-types',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});rows.value=await api<Accessory[]>('api/equipment/accessory-types')}active.value=id;selected.value=[id];status.value=0;notice.value=kind==='edit'?'配件類別已修改。':kind==='copy'?'配件類別與壽命設定已複製。':'配件類別已新增。';if(keep){mode.value='edit';form.value.accessoryType=id;audit.value.reviser=props.currentUserNo||'DEV001';audit.value.reviseDate=new Date().toLocaleString('zh-TW')}else mode.value=null}catch(e){error.value=e instanceof Error?e.message:'儲存失敗。'}finally{busy.value=false}}
async function removeMain():Promise<void>{if(!targets.value.length)return;if(!deleteAllowed.value){error.value='簽核中的資料不可刪除。';return}if(!confirm('確定刪除選取的 '+targets.value.length+' 筆配件類別？'))return;busy.value=true;try{if(mock.value){const ids=new Set(targets.value.map(x=>x.accessoryType));rows.value=read(keys.main,seedMain).filter(x=>!ids.has(x.accessoryType));write(keys.main,rows.value);write(keys.property,read(keys.property,seedProperties).filter(x=>!ids.has(x.accessory)));write(keys.life,read(keys.life,seedLife).filter(x=>!ids.has(x.accessory)))}else{for(const row of targets.value)await api<void>('api/equipment/accessory-types/'+encodeURIComponent(row.accessoryType),{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({issueState:row.issueState,dataStamp:row.dataStamp})});rows.value=await api<Accessory[]>('api/equipment/accessory-types')}selected.value=[];active.value='';query();notice.value='配件類別及其屬性、壽命資料已刪除。'}catch(e){error.value=e instanceof Error?e.message:'刪除失敗。'}finally{busy.value=false}}

async function approveMain():Promise<void>{if(!approveAllowed.value){error.value='只有未簽核資料可以核准。';return}if(!confirm('確定核准選取的 '+targets.value.length+' 筆資料？'))return;busy.value=true;try{if(mock.value){const ids=new Set(targets.value.map(x=>x.accessoryType));rows.value=read(keys.main,seedMain).map(x=>ids.has(x.accessoryType)?{...x,issueState:2,dataStamp:x.dataStamp+1,reviser:props.currentUserNo||'DEV001',reviseDate:new Date().toISOString()}:x);write(keys.main,rows.value)}else{for(const row of targets.value)await api<void>('api/equipment/accessory-types/'+encodeURIComponent(row.accessoryType)+'/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataStamp:row.dataStamp})});rows.value=await api<Accessory[]>('api/equipment/accessory-types')}selected.value=[];query();notice.value='配件類別已核准。'}catch(e){error.value=e instanceof Error?e.message:'核准失敗。'}finally{busy.value=false}}
async function openProperties():Promise<void>{if(!one.value){error.value='請先選取一筆配件類別。';return}propertyOpen.value=true;propertyError.value='';propertyNotice.value='';try{properties.value=mock.value?read(keys.property,seedProperties).filter(x=>x.accessory===one.value!.accessoryType&&x.accessoryVersion==='-1'):await api<Property[]>('api/equipment/accessory-types/'+encodeURIComponent(one.value.accessoryType)+'/properties?accessoryVersion=-1');propertyNo.value=properties.value[0]?.propertyNo||''}catch(e){propertyError.value=e instanceof Error?e.message:'屬性載入失敗。'}}
function openPropertyForm(next:Exclude<SubMode,null>):void{const row=properties.value.find(x=>x.propertyNo===propertyNo.value);if(next!=='add'&&!row){propertyError.value='請先選取一筆屬性。';return}if(next==='edit'&&row?.issueState!==0){propertyError.value='只有未簽核屬性可以修改。';return}propertyMode.value=next;propertyForm.value=next==='edit'&&row?{propertyNo:row.propertyNo,defaultValue:row.defaultValue||'',propertySequence:String(row.propertySequence??1),description:row.description||''}:{propertyNo:'',defaultValue:next==='copy'&&row?row.defaultValue||'':'',propertySequence:String(row?.propertySequence??1),description:next==='copy'&&row?row.description||'':''};propertyError.value=''}
async function saveProperty():Promise<void>{const accessory=one.value?.accessoryType,kind=propertyMode.value,id=propertyForm.value.propertyNo.trim(),seq=Number(propertyForm.value.propertySequence);if(!accessory||!kind)return;if(!id||id.length>20){propertyError.value='屬性編號必填且不可超過 20 個字元。';return}if(!Number.isInteger(seq)||seq<0||seq>99){propertyError.value='屬性順序需為 0 到 99 的整數。';return}if(kind!=='edit'&&properties.value.some(x=>x.propertyNo.toUpperCase()===id.toUpperCase())){propertyError.value='屬性編號已存在。';return}try{if(mock.value){const all=read(keys.property,seedProperties),now=new Date().toISOString(),i=all.findIndex(x=>x.accessory===accessory&&x.propertyNo===propertyNo.value);if(kind==='edit'&&i>=0)all[i]={...all[i],defaultValue:propertyForm.value.defaultValue||null,propertySequence:seq,description:propertyForm.value.description||null,dataStamp:all[i].dataStamp+1,reviser:props.currentUserNo||'DEV001',reviseDate:now};else{all.push({accessory,accessoryVersion:'-1',propertyNo:id.toUpperCase(),defaultValue:propertyForm.value.defaultValue||null,propertySequence:seq,description:propertyForm.value.description||null,issueState:0,dataStamp:0,creator:props.currentUserNo||'DEV001',createDate:now,reviser:null,reviseDate:null})}write(keys.property,all)}else{const path='api/equipment/accessory-types/'+encodeURIComponent(accessory)+'/properties';const body={accessoryVersion:'-1',propertyNo:id.toUpperCase(),defaultValue:propertyForm.value.defaultValue||null,propertySequence:seq,description:propertyForm.value.description||null};if(kind==='edit')await api<void>(path+'/'+encodeURIComponent(propertyNo.value),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});else await api<void>(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}propertyMode.value=null;await openProperties();propertyNotice.value='屬性已儲存。'}catch(e){propertyError.value=e instanceof Error?e.message:'屬性儲存失敗。'}}
async function deleteProperty():Promise<void>{const row=properties.value.find(x=>x.propertyNo===propertyNo.value),accessory=one.value?.accessoryType;if(!row||!accessory)return;if(![0,2,-1].includes(row.issueState)){propertyError.value='簽核中的屬性不可刪除。';return}if(!confirm('確定刪除屬性 '+row.propertyNo+'？'))return;try{if(mock.value)write(keys.property,read(keys.property,seedProperties).filter(x=>!(x.accessory===accessory&&x.propertyNo===row.propertyNo)));else await api<void>('api/equipment/accessory-types/'+encodeURIComponent(accessory)+'/properties/'+encodeURIComponent(row.propertyNo),{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({issueState:row.issueState,dataStamp:row.dataStamp})});await openProperties();propertyNotice.value='屬性已刪除。'}catch(e){propertyError.value=e instanceof Error?e.message:'屬性刪除失敗。'}}
async function approveProperty():Promise<void>{const row=properties.value.find(x=>x.propertyNo===propertyNo.value),accessory=one.value?.accessoryType;if(!row||!accessory)return;if(row.issueState!==0){propertyError.value='只有未簽核屬性可以核准。';return}try{if(mock.value){const all=read(keys.property,seedProperties).map(x=>x.accessory===accessory&&x.propertyNo===row.propertyNo?{...x,issueState:2 as State,dataStamp:x.dataStamp+1,reviser:props.currentUserNo||'DEV001',reviseDate:new Date().toISOString()}:x);write(keys.property,all)}else await api<void>('api/equipment/accessory-types/'+encodeURIComponent(accessory)+'/properties/'+encodeURIComponent(row.propertyNo)+'/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dataStamp:row.dataStamp})});await openProperties();propertyNotice.value='屬性已核准。'}catch(e){propertyError.value=e instanceof Error?e.message:'屬性核准失敗。'}}
async function openLife():Promise<void>{if(!one.value){error.value='請先選取一筆配件類別。';return}lifeOpen.value=true;lifeError.value='';lifeNotice.value='';const id=one.value.accessoryType;try{life.value=mock.value?structuredClone(read(keys.life,seedLife).find(x=>x.accessory===id)||newLife(id)):((await api<Life|null>('api/equipment/accessory-types/'+encodeURIComponent(id)+'/life'))||newLife(id))}catch(e){lifeError.value=e instanceof Error?e.message:'壽命設定載入失敗。'}}

function validateLife():string{if(life.value.lifeManage===0)return'';if(life.value.repairCycle===null&&life.value.timeCycle===null)return'啟用壽命管理時，請設定批數或週期管制。';if(life.value.repairCycle!==null&&(!Number.isInteger(+life.value.repairCycle)||+life.value.repairCycle<0))return'維修週期需為非負整數。';if(life.value.repairCycle!==null&&!life.value.lifeScript?.trim())return'依批數管制時，壽命公式為必填。';if(life.value.timeCycle!==null&&(!Number.isInteger(+life.value.timeCycle)||+life.value.timeCycle<1))return'管控週期需為大於 0 的整數。';if(life.value.repairable===null||life.value.lifeTolerance===null)return'請完成可維修與壽命容許設定。';if(life.value.repairable===1&&life.value.scrapType===null)return'可維修時需選擇報廢計算方式。';return''}
async function saveLife():Promise<void>{const issue=validateLife();if(issue){lifeError.value=issue;return}try{if(mock.value){const all=read(keys.life,seedLife),i=all.findIndex(x=>x.accessory===life.value.accessory),now=new Date().toISOString(),saved={...life.value,dataStamp:i>=0?all[i].dataStamp+1:0,creator:i>=0?all[i].creator:props.currentUserNo||'DEV001',createDate:i>=0?all[i].createDate:now,reviser:i>=0?props.currentUserNo||'DEV001':null,reviseDate:i>=0?now:null};if(i>=0)all[i]=saved;else all.push(saved);write(keys.life,all);life.value=saved}else await api<void>('api/equipment/accessory-types/'+encodeURIComponent(life.value.accessory)+'/life',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(life.value)});lifeError.value='';lifeNotice.value='配件壽命設定已儲存。'}catch(e){lifeError.value=e instanceof Error?e.message:'壽命儲存失敗。'}}
function disableLife():void{if(life.value.lifeManage===0){life.value.lifeScript='';life.value.repairable=null;life.value.repairCycle=null;life.value.scrapType=null;life.value.scrapLife=null;life.value.lifeTolerance=null;life.value.timeCycle=null;life.value.alertTime=null;life.value.alertCount=null}}
function csvColumns(line:string):string[]{const out:string[]=[];let cell='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'&&quoted){cell+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){out.push(cell.trim());cell=''}else cell+=c}out.push(cell.trim());return out}
async function readImport(event:Event):Promise<void>{const file=(event.target as HTMLInputElement).files?.[0];importRows.value=[];importError.value='';if(!file)return;importFile.value=file.name;if(!file.name.toLowerCase().endsWith('.csv')){importError.value='Development 預覽目前支援 CSV；WinForms Excel (.xlsx/.xls) 檔案解析與正式檢核由家用端 API 接手。';return}const lines=(await file.text()).replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());importRows.value=lines.slice(1).map(line=>{const c=csvColumns(line);return{accessoryType:c[0]||'',accessoryCategory:c[1]||'',description:c[2]||'',result:'待檢核',message:'尚未匯入'}})}
function importTemplate():void{const url=URL.createObjectURL(new Blob(['\uFEFFAccessoryType,AccessoryCategory,Description\r\nDEV-ACC-NEW,治具,開發用範例\r\n'],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='AccessoryTypeTemplate.csv';a.click();URL.revokeObjectURL(url)}
async function runImport():Promise<void>{if(!importRows.value.length){importError.value='請先選取含資料列的 CSV 檔案。';return}try{if(mock.value){const all=read(keys.main,seedMain),now=new Date().toISOString();for(const row of importRows.value){if(!row.accessoryType||!row.accessoryCategory){row.result='失敗';row.message='配件類別與配件分類為必填。';continue}if(!categories.value.some(x=>x.accessoryCategory===row.accessoryCategory)){row.result='失敗';row.message='找不到配件分類。';continue}if(all.some(x=>x.accessoryType.toUpperCase()===row.accessoryType.toUpperCase())){row.result='失敗';row.message='配件類別已存在。';continue}all.push({accessoryType:row.accessoryType.toUpperCase(),accessoryCategory:row.accessoryCategory,description:row.description||null,issueState:0,dataStamp:0,creator:props.currentUserNo||'DEV001',createDate:now,reviser:null,reviseDate:null});row.result='成功';row.message='已新增為未簽核資料。'}write(keys.main,all);rows.value=all}else{const result=await api<{results:{accessoryType:string;result:string;message:string}[]}>('api/equipment/accessory-types/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(importRows.value.map(({accessoryType,accessoryCategory,description})=>({accessoryType,accessoryCategory,description})))});for(const row of importRows.value){const item=result.results.find(x=>x.accessoryType===row.accessoryType);row.result=item?.result||'失敗';row.message=item?.message||'API 未回傳結果'}rows.value=await api<Accessory[]>('api/equipment/accessory-types')}query()}catch(e){importError.value=e instanceof Error?e.message:'匯入失敗。'}}
function closePage():void{history.pushState({},'',base||'/');dispatchEvent(new PopStateEvent('popstate'))}
onMounted(()=>{void load()})
watch(() => props.developmentPreview, () => { void load() })
</script>

<template>
  <section class="acc-page">
    <div class="filter-row">
      <label v-for="option in [{value:0,label:'未簽核'},{value:1,label:'簽核中'},{value:2,label:'已簽核'},{value:-1,label:'不使用'}]" :key="option.value" class="state-choice"><input v-model.number="status" type="radio" :value="option.value" @change="query"><span>{{option.label}}</span></label>
      <label for="acc-query">配件類別</label><input id="acc-query" v-model="keyword" maxlength="50" class="query-input" @keyup.enter="query"><span>%</span><button class="win-btn" type="button" @click="query">查詢</button>
    </div>
    <p v-if="mock" class="mock-note">Development 假資料：僅存於瀏覽器 localStorage，不會寫入 MES Oracle 或正式 API。</p>
    <p v-if="error" class="msg error">{{error}}</p><p v-if="notice" class="msg success">{{notice}}</p>
    <div class="workspace">
      <div class="grid-box"><div class="grid-scroll"><table class="acc-grid"><thead><tr><th class="check-col"></th><th>配件類別</th><th>說明</th><th>配件分類</th><th>建立人</th><th>建立日期</th><th>修改人</th><th>修改日期</th></tr></thead><tbody>
        <tr v-if="loading"><td colspan="8" class="empty">資料載入中…</td></tr><tr v-else-if="!visible.length"><td colspan="8" class="empty">查無資料</td></tr>
        <template v-else><tr v-for="row in visible" :key="row.accessoryType" :class="{active:active===row.accessoryType}" @click="selectRow(row)"><td class="check-col"><input type="checkbox" :checked="selected.includes(row.accessoryType)" @click.stop @change="toggle(row.accessoryType)"></td><td>{{row.accessoryType}}</td><td>{{row.description}}</td><td>{{row.accessoryCategory}}</td><td>{{row.creator}}</td><td>{{dateText(row.createDate)}}</td><td>{{row.reviser}}</td><td>{{dateText(row.reviseDate)}}</td></tr></template>

      </tbody></table></div><div class="count">資料總筆數 {{visible.length}}</div></div>
      <aside class="actions"><button class="win-btn primary" :disabled="busy" @click="openForm('add')">新增(A)</button><button class="win-btn" :disabled="busy||!editAllowed" @click="openForm('edit')">修改(E)</button><button class="win-btn" :disabled="busy||!one" @click="openForm('copy')">複製(C)</button><button class="win-btn" :disabled="busy||!approveAllowed" @click="approveMain">核准</button><button class="win-btn" :disabled="busy||!deleteAllowed" @click="removeMain">刪除(D)</button><button class="win-btn" :disabled="busy||!one" @click="openProperties">屬性</button><button class="win-btn" :disabled="busy||!one" @click="openLife">壽命管理</button><button class="win-btn" :disabled="busy" @click="importOpen=true;importRows=[];importError=''">資料匯入</button><button class="win-btn close" @click="closePage">關閉</button></aside>
    </div>

    <div v-if="mode" class="backdrop" @click.self="mode=null"><section class="dialog main-dialog" role="dialog" aria-modal="true"><header class="dialog-head"><h2>配件基本資料（{{mode==='add'?'新增':mode==='edit'?'修改':'複製'}}）</h2><button class="x" @click="mode=null">×</button></header><fieldset class="group"><legend>配件類別資料</legend>
      <label class="form-row"><span>配件類別</span><input v-model.trim="form.accessoryType" maxlength="50" :readonly="mode==='edit'" class="kd-input"></label>
      <label class="form-row"><span>配件分類</span><span class="picker"><input :value="form.accessoryCategory" readonly class="kd-input"><button class="win-btn" @click="picker=true">…</button></span></label>
      <label class="form-row description"><span>說明</span><textarea v-model="form.description" maxlength="255" class="kd-input"></textarea></label>
    </fieldset><div class="audit"><label>建立人<input :value="audit.creator" readonly></label><label>建立日期<input :value="audit.createDate" readonly></label><label>修改人<input :value="audit.reviser" readonly></label><label>修改日期<input :value="audit.reviseDate" readonly></label></div><p v-if="error" class="msg error">{{error}}</p><footer class="dialog-foot"><button class="win-btn primary" :disabled="busy" @click="saveMain(false)">確定</button><button class="win-btn" @click="mode=null">關閉</button><button class="win-btn" :disabled="busy" @click="saveMain(true)">套用</button></footer></section></div>
    <div v-if="picker" class="backdrop nested" @click.self="picker=false"><section class="dialog picker-dialog"><header class="dialog-head"><h2>選擇配件分類</h2><button class="x" @click="picker=false">×</button></header><button v-for="item in categories" :key="item.accessoryCategory" class="category-option" @click="form.accessoryCategory=item.accessoryCategory;picker=false"><b>{{item.accessoryCategory}}</b><span>{{item.description}}</span></button><p v-if="!categories.length" class="empty">目前沒有配件分類。</p></section></div>

    <div v-if="propertyOpen" class="backdrop" @click.self="propertyOpen=false"><section class="dialog sub-dialog"><header class="dialog-head"><h2>配件屬性｜{{one?.accessoryType}}（版本 -1）</h2><button class="x" @click="propertyOpen=false">×</button></header><div class="sub-actions"><button class="win-btn primary" @click="openPropertyForm('add')">新增</button><button class="win-btn" :disabled="!propertyNo" @click="openPropertyForm('edit')">修改</button><button class="win-btn" :disabled="!propertyNo" @click="openPropertyForm('copy')">複製</button><button class="win-btn" @click="deleteProperty">刪除</button><button class="win-btn" @click="approveProperty">核准</button></div><div class="grid-scroll"><table class="acc-grid"><thead><tr><th>屬性編號</th><th>預設值</th><th>順序</th><th>說明</th><th>狀態</th></tr></thead><tbody><tr v-for="row in properties" :key="row.propertyNo" :class="{active:propertyNo===row.propertyNo}" @click="propertyNo=row.propertyNo"><td>{{row.propertyNo}}</td><td>{{row.defaultValue}}</td><td>{{row.propertySequence}}</td><td>{{row.description}}</td><td>{{stateText(row.issueState)}}</td></tr><tr v-if="!properties.length"><td colspan="5" class="empty">查無屬性</td></tr></tbody></table></div><p v-if="propertyError" class="msg error">{{propertyError}}</p><p v-if="propertyNotice" class="msg success">{{propertyNotice}}</p><footer class="dialog-foot"><button class="win-btn" @click="propertyOpen=false">關閉</button></footer></section></div>
    <div v-if="propertyMode" class="backdrop nested"><form class="dialog mini-dialog" @submit.prevent="saveProperty"><header class="dialog-head"><h2>屬性定義</h2><button class="x" type="button" @click="propertyMode=null">×</button></header><label class="form-row"><span>屬性編號</span><input v-model.trim="propertyForm.propertyNo" maxlength="20" :readonly="propertyMode==='edit'" class="kd-input"></label><label class="form-row"><span>預設值</span><input v-model="propertyForm.defaultValue" maxlength="255" class="kd-input"></label><label class="form-row"><span>屬性順序</span><input v-model="propertyForm.propertySequence" type="number" min="0" max="99" class="kd-input"></label><label class="form-row"><span>說明</span><textarea v-model="propertyForm.description" maxlength="255" class="kd-input"></textarea></label><p v-if="propertyError" class="msg error">{{propertyError}}</p><footer class="dialog-foot"><button class="win-btn primary">確定</button><button type="button" class="win-btn" @click="propertyMode=null">關閉</button></footer></form></div>


    <div v-if="lifeOpen" class="backdrop" @click.self="lifeOpen=false"><section class="dialog life-dialog"><header class="dialog-head"><h2>配件壽命管理｜{{life.accessory}}</h2><button class="x" @click="lifeOpen=false">×</button></header><fieldset class="group"><legend>壽命管理</legend><div class="radio-row"><span>啟用壽命管理</span><label><input v-model.number="life.lifeManage" type="radio" :value="1">是</label><label><input v-model.number="life.lifeManage" type="radio" :value="0" @change="disableLife">否</label></div><template v-if="life.lifeManage===1"><label class="form-row"><span>壽命計算公式</span><textarea v-model="life.lifeScript" maxlength="200" class="kd-input"></textarea></label><label class="form-row"><span>批數管制</span><input v-model.number="life.repairCycle" type="number" min="0" class="kd-input"></label><label class="form-row"><span>批數警示</span><input v-model.number="life.alertCount" type="number" min="1" class="kd-input"></label><label class="form-row"><span>週期管制</span><input v-model.number="life.timeCycle" type="number" min="1" class="kd-input"></label><label class="form-row"><span>週期警示</span><input v-model.number="life.alertTime" type="number" min="1" class="kd-input"></label><div class="radio-row"><span>可維修</span><label><input v-model.number="life.repairable" type="radio" :value="1">是</label><label><input v-model.number="life.repairable" type="radio" :value="0">否</label></div><div class="radio-row"><span>報廢方式</span><label><input v-model.number="life.scrapType" type="radio" :value="0">維修次數</label><label><input v-model.number="life.scrapType" type="radio" :value="1">使用次數</label></div><label class="form-row"><span>報廢壽命</span><input v-model.number="life.scrapLife" type="number" min="0" class="kd-input"></label><div class="radio-row"><span>容許超過壽命</span><label><input v-model.number="life.lifeTolerance" type="radio" :value="1">是</label><label><input v-model.number="life.lifeTolerance" type="radio" :value="0">否</label></div></template></fieldset><p v-if="lifeError" class="msg error">{{lifeError}}</p><p v-if="lifeNotice" class="msg success">{{lifeNotice}}</p><footer class="dialog-foot"><button class="win-btn primary" @click="saveLife">確定</button><button class="win-btn" @click="lifeOpen=false">關閉</button><button class="win-btn" @click="saveLife">套用</button></footer></section></div>

    <div v-if="importOpen" class="backdrop" @click.self="importOpen=false"><section class="dialog import-dialog"><header class="dialog-head"><h2>配件類別資料匯入</h2><button class="x" @click="importOpen=false">×</button></header><div class="import-file"><input type="file" accept=".csv,.xlsx,.xls" @change="readImport"><button class="win-btn" @click="importTemplate">下載範本</button></div><p class="file-name">{{importFile}}</p><div class="grid-scroll"><table class="acc-grid"><thead><tr><th>配件類別</th><th>配件分類</th><th>說明</th><th>結果</th><th>訊息</th></tr></thead><tbody><tr v-for="(row,i) in importRows" :key="i"><td>{{row.accessoryType}}</td><td>{{row.accessoryCategory}}</td><td>{{row.description}}</td><td>{{row.result}}</td><td>{{row.message}}</td></tr><tr v-if="!importRows.length"><td colspan="5" class="empty">請選取 CSV 檔案。</td></tr></tbody></table></div><p v-if="importError" class="msg error">{{importError}}</p><footer class="dialog-foot"><button class="win-btn primary" @click="runImport">匯入</button><button class="win-btn" @click="importOpen=false">關閉</button></footer></section></div>
  </section>
</template>

