;flex-wrap:wrap;padding:10px}.sub-dialog .grid-scroll,.import-dialog .grid-scroll{max-height:56vh;margin:0 10px;border:1px solid #bbb}.mini-dialog{width:min(560px,94vw);padding-bottom:4px}.mini-dialog .form-row{margin:12px 16px}.life-dialog{width:min(880px,97vw)}.radio-row{display:flex;align-items:center;gap:18px;min-height:34px;margin:8px 0}.radio-row>span:first-child{width:150px;text-align:right}.radio-row label{display:flex;align-items:center;gap:5px}.file-name{margin:0 14px;color:#666}
